FUNCTION check_dept(p_dept_id NUMBER) RETURN NUMBER IS
    v_count NUMBER;
BEGIN
    SELECT COUNT(*) INTO v_count FROM employees WHERE department_id = p_dept_id;
    RETURN v_count;
END;
